    ["Press Ctrl+C to copy:"] = "Нажмите Ctrl+C, чтобы скопировать:",
    ["Preview follows the current castbar visibility, icon, text, and global color settings."] = "Предварительный просмотр соответствует текущей видимости панели приведения, значку, тексту и глобальным настройкам цвета.",
