    ["shared bar textures, gradients, rounded frame corners, absorb display, outlines, highlight borders, power smoothing and all per-unit/group bar overrides"] = "общие текстуры полос, градиенты, закругленные углы рамок, поглощающее отображение, контуры, выделение границ, мощное сглаживание и все переопределения полос /group для каждого модуля.",
    ["shared font family, text style, name/power text coloring, name shortening and all per-unit/group font overrides"] = "общее семейство шрифтов, стиль текста, раскраска текста name/power, сокращение имени и все переопределения шрифтов /group для каждого модуля",
