L["Preserve HP color keeps the HP fill color while layer fade is active and draws missing health separately with the same HP track color from Colors.\n\nThis can help when HP Bar fade makes the empty HP area disappear or look black. Some custom textures may still look flat, dark, or different while this option is enabled."] = "Сохранение цвета HP удерживает цвет заполнения HP, пока активно затухание слоя, и отдельно рисует недостающее здоровье тем же цветом дорожки HP из раздела цветов.\n\nЭто помогает, когда затухание полосы HP делает пустую область невидимой или черной. Некоторые пользовательские текстуры при этой опции все равно могут выглядеть плоскими, темными или иначе."
L["Reset %s to defaults?\n\nThis resets %s for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "Сбросить %s к значениям по умолчанию?\n\nЭто сбросит %s для активного профиля. Значения по умолчанию читаются из текущего заводского профиля MSUF, поэтому будущие изменения значений по умолчанию будут использоваться автоматически."
L["Reset %s to defaults?\n\nThis resets the entire active profile '%s' to the current MSUF factory defaults. Every menu in that profile will be affected."] = "Сбросить %s к значениям по умолчанию?\n\nЭто сбросит весь активный профиль '%s' к текущим заводским значениям MSUF. Будет затронуто каждое меню в этом профиле."
L["Reset Scopes"] = "Сбросить области"

--- MSUF runtime coverage copied into direct locale file
L["                   Confirm stages the reset; reload via /reload or MSUF Menu > Advanced > Factory Reset."] = "                   Подтверждение подготовит сброс; перезагрузите через /reload или используйте Меню MSUF > Дополнительно > Заводской сброс."
L["  !msuf help      - Print this help via chat (from your own character)."] = "  !msuf help      - Вывести эту справку в чат (от вашего персонажа)."
L["  (then /reload OR MSUF Menu > Advanced > Factory Reset)"] = "  (затем /reload ИЛИ Меню MSUF > Дополнительно > Заводской сброс)"
L["  /msuf absorb    - Toggle showing total absorb amount in HP text."] = "  /msuf absorb    - Включить или выключить общую величину поглощения в тексте здоровья."
L["  /msuf analytics off|on|status - Toggle Wago Analytics beta telemetry."] = "  /msuf analytics off|on|status - Управление бета-телеметрией Wago Analytics."
L["  /msuf fullreset - FULL factory reset (all profiles/settings)."] = "  /msuf fullreset - ПОЛНЫЙ заводской сброс (все профили/настройки)."
L["  /msuf gfhoverdebug on|off|status - Debug group-frame hover + tooltip paths."] = "  /msuf gfhoverdebug on|off|status - Отладка наведения групповых фреймов и путей подсказок."
L["  /msuf help      - Show this help."] = "  /msuf help      - Показать эту справку."
L["  /msuf reset     - Reset all MSUF frame positions and visibility to defaults."] = "  /msuf reset     - Сбросить положения и видимость всех фреймов MSUF."
L["  /msufdbgpos     - Toggle position drift debugger (overlay + chat log)."] = "  /msufdbgpos     - Переключить отладчик смещения позиции (оверлей + журнал чата)."
L["  /rl             - Reload the UI."] = "  /rl             - Перезагрузить интерфейс."
L["%s  -  %d sections. Click to view the bundled changelog."] = "%s  -  разделов: %d. Нажмите, чтобы открыть встроенный журнал изменений."
