L["Blizzard controls this aura block, so MSUF cannot drag it. Switch to MSUF Custom mode if you want full positioning control. The preview marks the Blizzard-owned area."] = "Blizzard управляет этим блоком аур, поэтому MSUF не может его перетаскивать. Переключитесь на пользовательский режим MSUF для полного контроля позиции. Предпросмотр отмечает область Blizzard."
L["Blizzard locked"] = "Заблокировано Blizzard"
L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. Dispel Glow is unavailable only for Group Frame scopes where Blizzard controls the aura layer."] = "Режим Blizzard позволяет WoW размещать выбранные типы аур. Пользовательский режим MSUF дает MSUF контроль размера, роста, позиции, фильтров и стиля аур. Свечение рассеивания недоступно только для областей групповых фреймов, где Blizzard управляет слоем аур."
L["Blizzard renders cooldown/stack text for native Buffs and Debuffs. These text overlay fields only affect custom icons."] = "Blizzard отображает текст восстановления и стаков для стандартных баффов и дебаффов. Эти поля текстового оверлея влияют только на пользовательские значки."
