L["EM_HELP_BTN"] = "? Справка"
L["EM_HELP_BTN_TIP"] = "Открывает полную пошаговую настройку MSUF\nс раздела режима редактирования."
L["EM_HELP_CDM"] = "|cff60a5ffCDM|r переключает глобальный якорь Essential Cooldown Manager. |cff60a5ffAnchor|r открывает выбор якоря; наведите на именованный фрейм, удерживайте Ctrl и нажмите левую кнопку, чтобы использовать его как глобальный якорь. Выбор пользовательского якоря отключает CDM."
L["EM_HELP_COPYTO"] = "В окнах юнита и полосы применения |cff60a5ffCopy To|r копирует настройки текущего окна на другую цель. Копирование фрейма юнита сохраняет позицию и якорь цели; копирование полосы сохраняет смещения X/Y цели."
L["EM_HELP_DRAG"] = "Удерживайте левую кнопку мыши на оверлее перемещателя и перетащите его. Живой фрейм следует за перемещателем, а показания X/Y под оверлеем показывают текущее смещение на экране. Отпустите кнопку, чтобы сохранить позицию."
L["EM_HELP_EXIT"] = "|cff60a5ffExit|r выходит из режима редактирования и сохраняет текущие изменения. Вход в бой также выводит из режима редактирования. Escape закрывает или отменяет окно; кнопка Exit на HUD - обычный способ выхода."
L["EM_HELP_NUDGE"] = "Стрелки перемещают активную цель. Приоритет: выбранный маркер предпросмотра, открытое окно полосы применения, открытое окно ауры, затем выбранный фрейм юнита. Шаг: 1 px, Shift = 5 px, Ctrl = 10 px, Alt = текущий шаг сетки."
L["EM_HELP_OPACITY"] = "Прокрутите элемент |cff60a5ffBG ##%|r, чтобы изменить только прозрачность фона режима редактирования. Это не меняет прозрачность фреймов юнитов или сохраненную видимость."
L["EM_HELP_POPUP"] = "Левый клик по перемещателю без перетаскивания открывает его окно редактирования. Окна юнитов редактируют размер, позицию, якоря текста, настройки отдельной ресурсо-полосы и копирование на другой юнит. Перемещатели полос и аур открывают свои отдельные окна."
L["EM_HELP_PREVIEW"] = "|cff60a5ffPreview|r переключает фиктивные данные для отсутствующих цели, фокуса, цели цели, питомца, боссов и предпросмотров полос, пока активен режим редактирования. |cff60a5ffAuras|r переключает значки предпросмотра аур и коробки перемещения аур."
L["EM_HELP_SNAP"] = "Сетка - визуальная подсказка. Левый клик по |cff60a5ffGrid ##px|r включает или выключает линии сетки; прокрутка меняет расстояние. |cff60a5ffSnap|r отдельно: если включено, перемещатели привязываются к центру экрана или к краям/центрам других видимых перемещателей, с оранжевыми направляющими."
L["EM_HELP_TITLE"] = "Режим редактирования - краткая справка"
L["EM_HELP_UNDO"] = "|cff60a5ffUndo|r и |cff60a5ffRedo|r восстанавливают последние изменения режима редактирования, сохраненные перед перетаскиванием, сдвигами и изменениями в окнах. |cff60a5ffCancel All|r запрашивает подтверждение, восстанавливает снимок до входа в режим редактирования, затем выходит."
