L["Reduced redundant castbar re-layout work when width-source geometry has not changed."] = "Сокращена лишняя повторная раскладка полос заклинаний, когда геометрия источника ширины не менялась."
L["Reduced unnecessary group frame header rescans during rebuild and layout bursts."] = "Сокращены лишние пересканирования заголовков групповых фреймов при перестроении и резких обновлениях раскладки."
