L["Reset all Group Frame settings to defaults?\n\nThis resets Party, Raid, and Mythic Raid Group Frames for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "Сбросить все настройки групповых фреймов?\n\nЭто сбросит фреймы группы, рейда и эпохального рейда для активного профиля. Значения берутся из текущего заводского профиля MSUF, поэтому будущие изменения стандартов будут применяться автоматически."
