L["Checked categories hide MSUF custom debuff icons only. Blizzard-rendered debuffs bypass this list while Use Blizzard: Debuffs is enabled."] = "Отмеченные категории скрывают только пользовательские значки дебаффов MSUF. Дебаффы, отрисованные Blizzard, обходят этот список, пока включено Использовать Blizzard: дебаффы."
