L["Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, dispel overlay, debuff stripe, and range fade. Heal prediction is in Global Style > Bars > Absorb Display."] = "Откройте Групповые фреймы > Здоровье и текст. Там настраиваются цвета здоровья, полосы, полоса ресурса, текст, наложение рассеивания, полоса ослаблений и затухание по дальности. Прогноз лечения находится в Глобальный стиль > Полосы > Отображение поглощений."
L["Open Unit Auras > Global Ignore List. It can hide predefined aura categories for all unit frames, or per unit after enabling Override for this unit. MSUF does not currently have an ElvUI-style freeform spell-ID blacklist for arbitrary debuffs."] = "Откройте Ауры юнитов > Глобальный список игнорирования. Он может скрывать предустановленные категории аур для всех фреймов юнитов или отдельно для юнита после включения переопределения для этого юнита. Сейчас в MSUF нет свободного черного списка ID заклинаний в стиле ElvUI для любых ослаблений."
L["Open this section to enable or disable rounded frame textures and its per-surface toggles."] = "Откройте этот раздел, чтобы включить или отключить скругленные текстуры фреймов и отдельные переключатели для поверхностей."
