L["Open Settings"] = "Открыть настройки"
L["Keep Selected"] = "Сохранить выбранное"
L["Double-click or use the settings button to open this element's settings."] = "Дважды щелкните или воспользуйтесь кнопкой настроек, чтобы открыть настройки этого элемента."
L["Right-click opens quick actions."] = "Щелчок правой кнопкой мыши открывает быстрые действия."
L["double-click/settings opens options - right-click actions - arrows nudge"] = "двойной щелчок /settings открывает параметры – действия по щелчку правой кнопкой мыши – перемещение стрелок"
L["drag handles - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "перетаскивание маркеров — двойной щелчок /settings открывает параметры — действия щелчка правой кнопкой мыши — Ctrl+колесико масштабирования"
L["Click a handle to select - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "Щелкните маркер, чтобы выбрать — двойной щелчок /settings открывает параметры — действия щелчка правой кнопкой мыши — Ctrl+колесико масштабирования"
L["Preview tip: drag handles to move, double-click or use settings to open options, right-click for actions."] = "Совет по предварительному просмотру: перетаскивайте маркеры для перемещения, дважды щелкните или используйте настройки, чтобы открыть параметры, щелкните правой кнопкой мыши для действий."
L["Hide right % sign"] = "Скрыть вправо % sign"
