L["Hide center % sign"] = "Скрыть центр % sign"
L["Group frames were enabled or disabled.\n\nA UI reload is required to fully apply this change.\n\nReload now?"] = "Групповые фреймы были включены или отключены. \n\nA Для полного применения этого изменения требуется перезагрузка пользовательского интерфейса. \n\nПерезагрузить сейчас?"
L["|cffffd700MSUF:|r Group frames were enabled or disabled. Reload the UI with /reload."] = "|cffffd700MSUF:|r Групповые фреймы были включены или отключены. Перезагрузите пользовательский интерфейс с помощью /reload."
L["Portrait zoom"] = "Портретный зум"
