L["Class resource preview and quick setup"] = "Предварительный просмотр ресурсов класса и быстрая настройка"
L["Preview controls = inspect layouts and states · MSUF Edit Mode = whole-frame placement"] = "Элементы управления предварительным просмотром = проверка макетов и состояний · Режим редактирования MSUF = размещение всего фрейма"
L["Drag = inner position · gear/double-click = options · right-click = actions · Ctrl-wheel/drag = zoom/pan · Edit Mode = whole frame"] = "Перетаскивание = внутреннее положение · шестерня/double-click = параметры · щелчок правой кнопкой мыши = действия · колесо Ctrl/drag = масштабирование/pan · Режим редактирования = весь фрейм"
L["%s is highlighted. Adjust it live, keep it as is, or continue."] = "%s выделен. Настройте его в реальном времени, оставьте как есть или продолжайте."
L["Your focus: %s, with %s information."] = "Ваше внимание: %s с информацией %s."
L["Choose one answer in each row. You can skip this personal step at any time."] = "Выберите один ответ в каждой строке. Вы можете пропустить этот личный шаг в любое время."
L["Drag whole frames, use arrows for precision, and Exit to keep your placement."] = "Перетаскивайте целые фреймы, используйте стрелки для точности и нажмите «Выход», чтобы сохранить свое расположение."
L["Start with Preview, then follow each highlighted frame section."] = "Начните с предварительного просмотра, затем следуйте за каждым выделенным участком фрейма."
L["Raid focus: compare Raid and Mythic scopes before reviewing each highlighted section."] = "Фокус рейда: сравните масштабы рейда и эпохального режима, прежде чем просматривать каждый выделенный раздел."
L["Solo focus: keep group defaults or prepare the Party scope for occasional groups."] = "Соло-фокус: сохраните групповые настройки по умолчанию или подготовьте пространство группы для случайных групп."
L["Dungeon focus: begin with Party or Mythic scope, then review each highlighted section."] = "Фокус на подземельях: начните с партийного или эпохального режима, затем просмотрите каждый выделенный раздел."
L["Compare the Party, Raid or Mythic scope that matters to you, then follow the highlights."] = "Сравните масштабы партийного, рейдового или эпохального режимов, которые вам интересны, а затем проследите за основными моментами."
L["Sample = visual only · tests = temporary · scope = shared/unit/group"] = "Образец = только визуально · тесты = временный · область действия = общий/unit/group"
L["Simulate casts here; position castbar handles in Preview or MSUF Edit Mode."] = "Имитация приведения здесь; расположить маркеры панели приведения в режиме предварительного просмотра или редактирования MSUF."
L["Use the scope selector for shared, unit and group text; compare readability in Preview."] = "Используйте селектор области для общего текста, текста подразделения и группы; Сравните читабельность в Preview."
L["Live/Dummy = display only · colored handles = saved positions · scope = shared/unit/group/custom"] = "Live/Dummy = только отображение · цветные маркеры = сохраненные позиции · область действия = общий /unit/group/custom"
L["Use the interactive preview for layouts and states; use Edit Mode for whole-frame placement."] = "Используйте интерактивный предварительный просмотр макетов и состояний; используйте режим редактирования для размещения всего фрейма."
L["Finish with a profile check and export a backup of your setup."] = "Завершите проверку профиля и экспортируйте резервную копию ваших настроек."
L["Review your choices and skipped areas. Finish adds no extra setting changes."] = "Просмотрите свой выбор и пропущенные области. Finish не добавляет никаких дополнительных изменений настроек."
L["Clarity focus: prefer the simplest readable option in each highlighted section."] = "Акцент на ясности: отдайте предпочтение самому простому и читабельному варианту в каждом выделенном разделе."
L["Combat-detail focus: inspect indicators, timers and visibility in each highlighted section."] = "Фокус на деталях боя: проверяйте индикаторы, таймеры и видимость в каждом выделенном разделе."
L["Review the highlighted sections; previews update while your changes autosave."] = "Просмотрите выделенные разделы; предварительный просмотр обновляется, а изменения автоматически сохраняются."
