L["Keeps current values unchanged and advances."] = "Сохраняет текущие значения неизменными и продвигается вперед."
L["Shows an inline impact warning before skipping."] = "Показывает встроенное предупреждение о воздействии перед пропуском."
L["Opens the next guided section or stage."] = "Открывает следующий управляемый раздел или этап."
L["Closes the menu while preserving guided setup progress."] = "Закрывает меню с сохранением хода пошаговой настройки."
L["Personalizes guided setup hints without changing MSUF settings."] = "Персонализирует подсказки по настройке без изменения настроек MSUF."
L["Two quick choices make the guide fit how you play."] = "Два быстрых выбора помогут подобрать руководство под ваш стиль игры."
L["Where do you spend most of your time?"] = "Где вы проводите большую часть своего времени?"
L["How much combat information should stand out?"] = "Сколько боевой информации должно выделяться?"
L["Navigate and find"] = "Перемещайтесь и найдите"
L["Use the left rail for pages and Search for an exact native control."] = "Используйте левую направляющую для страниц и выполните поиск точного встроенного элемента управления."
L["Autosave and history"] = "Автосохранение и история"
L["Changes autosave. Undo and Redo restore recent edits; Pause saves this exact tour position."] = "Изменения автосохраняются. «Отменить» и «Повторить» восстанавливают последние изменения; Пауза сохраняет именно эту позицию тура."
L["Reset with intent"] = "Сброс с намерением"
L["Reset All affects only the current supported page and asks first."] = "Сбросить все влияет только на текущую поддерживаемую страницу и запрашивает сначала."
L["Move whole frames safely"] = "Безопасное перемещение целых фреймов"
L["Preview moves inner elements; MSUF Edit Mode places complete frames."] = "Предварительный просмотр перемещает внутренние элементы; В режиме редактирования MSUF размещаются полные фреймы."
L["What you can move"] = "Что вы можете переместить"
L["Unitframes, supported castbars, group containers, aura groups and the tooltip preview. Boss 1 moves the shared Boss layout."] = "Юнитфреймы, поддерживаемые панели приведения, групповые контейнеры, группы аур и предварительный просмотр всплывающей подсказки. Босс 1 перемещает общий макет Босса."
L["Drag, select and align"] = "Перетащите, выберите и выровняйте"
L["Drag to place; click for quick controls. Arrow keys nudge, while Grid and Snap align."] = "Перетащите на место; нажмите для быстрого управления. Клавиши со стрелками перемещаются, а сетки и привязки выравниваются."
L["Undo, Cancel All, Exit"] = "Отменить, отменить все, выйти"
L["Undo and Redo affect individual moves. Cancel All restores the entry snapshot; Exit keeps your work."] = "Отмена и повтор влияют на отдельные ходы. Отменить все восстанавливает снимок записи; Выход сохранит вашу работу."
L["Combat pauses safely"] = "Бой благополучно приостанавливается"
L["Combat closes the menu and Edit Mode but keeps changes made so far. Reopen MSUF afterward to resume here."] = "Бой закрывает меню и режим редактирования, но сохраняет внесенные изменения. Затем снова откройте MSUF, чтобы возобновить работу здесь."
