L["Spell-specific channel tick markers"] = "Маркеры канала для конкретных заклинаний"
L["Runs a short castbar for the global cooldown whenever an instant spell triggers it.\n\nThe fill and time text are driven natively by the client from the real (haste-scaled) GCD duration - no per-frame addon work while the bar runs. A real cast, channel or empower always takes priority."] = "Показывает короткую полосу применения для глобального восстановления, когда мгновенное заклинание его запускает.\n\nЗаполнение и текст времени обрабатываются клиентом нативно на основе реальной (с учётом скорости) длительности ГКД - без покадровой работы аддона, пока полоса активна. Настоящее применение, поддерживаемое или усиленное заклинание всегда имеет приоритет."
L["Shows tick separators on the Player castbar while channeling.\n\nSupported spells use their actual tick count, including supported talent and channel-duration changes. Unsupported channels keep five evenly spaced fallback lines. Custom channel tick settings override the automatic layout.\n\nThe markers are event-driven and add no recurring channel polling."] = "Показывает разделители делений на панели каста игрока во время поддержания. \n\nПоддерживаемые заклинания используют фактическое количество тактов, включая поддерживаемые таланты и изменения длительности канала. Неподдерживаемые каналы сохраняют пять резервных линий, расположенных на равном расстоянии друг от друга. Настройки отметки пользовательского канала переопределяют автоматический макет. \n\nМаркеры управляются событиями и не добавляют повторяющегося опроса каналов."
L["Class Color (Reaction fallback)"] = "Цвет класса (резервный вариант реакции)"
L["Ready color (kick available)"] = "Готовый цвет (возможен пинок)"
L["Not ready color (kick on cooldown)"] = "Не готовый цвет (удар по перезарядке)"
L["PvP Flag (War Mode/PvP)"] = "PvP-флаг (режим войны/PvP)"
L["Abbreviate HP values (K/M)"] = "Сокращенные значения HP (K/M)"
L["For specializations that use mana alongside another resource."] = "Для специализаций, использующих ману наряду с другим ресурсом."
L["Smooths resource changes. Runes, Essence recharge, and timers keep their own animation."] = "Сглаживает изменения ресурсов. Руны, перезарядка сущности и таймеры сохраняют собственную анимацию."
L["Exact Spell IDs are used when Blizzard exposes them."] = "Точные идентификаторы заклинаний используются, когда Blizzard их предоставляет."
L["Reverses only the swipe overlay. Icon size and position stay unchanged."] = "Отменяет только наложение смахивания. Размер и положение значка остаются неизменными."
L["Only relevant sorting methods are shown for buffs and debuffs."] = "Для баффов и дебаффов показаны только соответствующие методы сортировки."
L["Reversed flips the complete priority order."] = "Обратный переворачивает полный порядок приоритетов."
