L["No blocked spells. Add one above or use a preset."] = "Никаких заблокированных заклинаний. Добавьте один из вышеперечисленных или используйте предустановку."
L["No blocked spells. Add one from the presets above."] = "Нет заблокированных заклинаний. Добавьте одно из предустановок выше."
L["No layers match this search."] = "Ни один слой не соответствует этому запросу."
