L["Shows all configurable MSUF layers on the unified 0-30 scale."] = "Показывает все настраиваемые слои MSUF по единой шкале от 0 до 30."
L["Shows every configurable MSUF layer on the unified 0-30 scale."] = "Показывает каждый настраиваемый слой MSUF по единой шкале от 0 до 30."
L["Slot "] = "Слот"
L["Sort mode"] = "Режим сортировки"
L["Spell Icons by spec"] = "Иконки заклинаний по спецификациям"
L["Spell Text Behavior"] = "Поведение текста заклинания"
L["Spell icon"] = "Значок заклинания"
