L["Portrait Cast Icon"] = "Значок заклинания на портрете"
L["The same setting as Portrait > More Options. It swaps the portrait for the spell icon while the unit casts, so the portrait has to be enabled."] = "Та же настройка, что и в разделе «Портрет > More Options». Она заменяет портрет значком заклинания во время произнесения, поэтому портрет должен быть включён."
L["Starts this frame effect when the aura reaches the selected time remaining. Permanent auras never trigger it."] = "Запускает этот эффект фрейма, когда аура достигает оставшегося выбранного времени. Постоянные ауры никогда не вызывают его."
L["Startup"] = "Стартап"
L["Status & Indicators"] = "Статус и индикаторы"
L["Style area"] = "Область стиля"
L["Style stays here under Appearance > Auras. Filters and lists now live directly in each frame's matching Aura menu."] = "Стиль остается здесь, в разделе «Внешний вид» > «Ауры». Фильтры и списки теперь находятся непосредственно в соответствующем меню Aura каждого фрейма."
L["Switch to Party scope to edit this feature."] = "Переключитесь на область «Группа», чтобы изменить эту функцию."
L["TOOLTIP"] = "ПОДПИСКА"
L["Tank, DPS, Healer"] = "Танк, ДПС, Целитель"
L["Tank, Healer, DPS"] = "Танк, Целитель, ДПС"
L["Target Highlight"] = "Целевое выделение"
L["Target highlight"] = "Целевое выделение"
L["Test prediction bars"] = "Тестовые панели прогнозов"
L["Text Colors"] = "Цвета текста"
L["Text, cooldown, stack and marker styling."] = "Текст, время восстановления, стиль стека и маркера."
L["Textures, gradients, outlines and highlight borders."] = "Текстуры, градиенты, контуры и выделение границ."
L["The next checkpoint unlocks after a real Party-frame position change."] = "Следующая контрольная точка разблокируется после реального изменения положения в фрейме вечеринки."
L["The placement step completes after you drag the highlighted frame once."] = "Шаг размещения завершится после того, как вы один раз перетащите выделенный фрейм."
L["The required Edit Mode movement is complete."] = "Требуемое перемещение в режиме редактирования завершено."
L["This buff"] = "Этот бафф"
L["This preview layer is locked."] = "Этот слой предварительного просмотра заблокирован."
L["Timer and marker colors are shared by unit and group aura previews."] = "Цвета таймера и маркера используются в предварительном просмотре аур юнитов и групп."
L["Timer urgency, ownership, stacks and pandemic state."] = "Срочность таймера, владение, стеки и состояние пандемии."
L["Tune Party range fade"] = "Диапазон Tune Party исчезает"
L["Two arrows point to a movable frame. Drag it once; Next unlocks after a real position change."] = "Две стрелки указывают на подвижную рамку. Перетащите его один раз; Далее разблокируется после реального изменения позиции."
L["Type a new value, then press Enter."] = "Введите новое значение и нажмите Enter."
L["UNLOCK, THEN CHANGE IT - Enable Corner Indicators, choose a slot, then select Custom Spell when requested."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ ЕГО. Включите угловые индикаторы, выберите слот, затем выберите «Пользовательское заклинание», когда потребуется."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spec, then press a tracked spell tile."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ. Включите индикаторы заклинаний, выберите специализацию, затем нажмите на плитку отслеживаемого заклинания."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then select a Frame Effect."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ. Включите индикаторы заклинаний, выберите заклинание, затем выберите эффект фрейма."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then set Indicator Type."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ. Включите индикаторы заклинаний, выберите заклинание, затем установите тип индикатора."
L["UNLOCK, THEN CHANGE IT - Enable the parent feature in this section first."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ. Сначала включите родительскую функцию в этом разделе."
L["UNLOCK, THEN CHANGE IT - Turn on Spell Indicators in the earlier checkpoint; use Back if you skipped it."] = "РАЗБЛОКИРОВАТЬ, ЗАТЕМ ИЗМЕНИТЬ — включите индикаторы заклинаний на предыдущей контрольной точке; используйте «Назад», если вы пропустили его."
L["Unit frame status icons are on each unit page. Group Spell Indicators are in Group Frames > Auras; group status and corner indicators are in Group Frames > Status & Indicators."] = "Значки состояния блока находятся на каждой странице объекта. Индикаторы групповых заклинаний находятся в разделе «Групповые рамки» > «Ауры»; Статус группы и угловые индикаторы находятся в разделе «Групповые рамки» > «Состояние и индикаторы»."
L["Unitframe Cooldown Manager anchoring"] = "Привязка Unitframe Cooldown Manager"
L["Unitframe auras"] = "Юнитфреймовые ауры"
L["Unitframe castbar"] = "Литая панель Unitframe"
L["Use Global"] = "Используйте глобальный"
