L["Use Global Style > Bars for highlight borders and Group Frames > Status & Indicators for role, threat, dispel, corner, and raid-marker indicators. Spell Indicators are in Group Frames > Auras."] = "Используйте «Глобальный стиль» > «Полосы» для выделения границ и «Групповые рамки» > «Статус и индикаторы» для индикаторов роли, угрозы, рассеивания, угла и маркера рейда. Индикаторы заклинаний находятся в разделе «Групповые рамки» > «Ауры»."
L["Use Global follows the Unitframe Global Coloring mode from Colors. Other choices override only this frame."] = "Использовать Global следует режиму глобальной раскраски Unitframe из Colors. Другие варианты переопределяют только этот фрейм."
L["Use MSUF group frames"] = "Использовать групповые фреймы MSUF"
L["Use both IDs"] = "Используйте оба идентификатора"
L["Use custom aura style for this scope"] = "Использовать собственный стиль ауры для этой области."
L["Use default icon"] = "Использовать значок по умолчанию"
L["Use the highlighted action now."] = "Используйте выделенное действие сейчас."
