L["YOUR MOVE - Click the highlighted Player mover to open its Width and Height popup."] = "ВАШ ДВИЖЕНИЕ — щелкните выделенный элемент перемещения игрока, чтобы открыть всплывающее окно «Ширина и высота»."
L["YOUR MOVE - Open Edit Mode, drag Party Frames once, then click the mover to see its Width, Height, and Spacing popup."] = "ВАШ ДВИЖЕНИЕ – откройте режим редактирования, перетащите рамки вечеринки один раз, затем нажмите на перемещатель, чтобы увидеть всплывающие окна \"Ширина\", \"Высота\" и \"Интервал\"."
L["YOUR MOVE - Press Open MSUF Edit Mode, then drag the double-arrow frame once."] = "ВАШ ПЕРЕХОД. Нажмите «Открыть режим редактирования MSUF», затем один раз перетащите рамку с двойной стрелкой."
