-- MSUF FULL CORE MENU SOURCE INVENTORY 2
-- Generated missing non-Assistant core keys for ruRU.
L["+"] = "+"
L["Can Priority Frames automatically select healers, DPS, classes, or specs?"] = "Могут ли рамки приоритета автоматически выбирать целителей, урон в секунду, классы или специализации?"
L["Can Priority Frames automatically show Augmentation Evokers?"] = "Могут ли рамки приоритета автоматически отображать вызывающие улучшения?"
L["Can Priority Frames show my co-tank?"] = "Могут ли Priority Frames показывать мой второй танк?"
L["Can Priority Frames update during combat?"] = "Могут ли рамки приоритета обновляться во время боя?"
L["Check that Priority Frames are enabled, you are grouped, and the matching base Party or Raid frames are enabled. Confirm that an assigned tank or manually pinned player is currently in the group and Visible slots is not full. Saved absent players create no empty placeholders, and protected roster changes made in combat finish after combat ends."] = "Убедитесь, что рамки приоритета включены, вы сгруппированы и включены соответствующие базовые рамки вечеринки или рейда. Убедитесь, что назначенный танк или игрок, закрепленный вручную, в настоящее время находится в группе, а видимые слоты не заполнены. Сохраненные отсутствующие игроки не создают пустых заполнителей, а изменения в защищенном составе вносятся в конце боя после его окончания."
L["Class Color and Health Gradient are runtime colors, not a single editable swatch."] = "Цвет класса и градиент здоровья — это цвета времени выполнения, а не один редактируемый образец."
L["Cleave Training Dummy"] = "Тренировочный манекен раскола"
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "Пользовательские 1–3 всегда сохраняются для каждого фрейма. Здесь только меняются стиль значков и полнокадровые эффекты."
L["Disabled or whitelist empty"] = "Отключено или белый список пуст"
L["Do Priority Frame pins persist, and what order do they use?"] = "Сохраняются ли контакты приоритетного фрейма и в каком порядке они используются?"
L["Do Priority Frames inherit click casting and appearance?"] = "Наследуют ли приоритетные фреймы преобразование и внешний вид кликов?"
L["Do Priority Frames use polling?"] = "Используют ли приоритетные фреймы опрос?"
L["Do Priority Frames work in parties and dungeons?"] = "Работают ли рамки приоритета в группах и подземельях?"
L["Enter text"] = "Введите текст"
L["Existing Priority frames remain usable in combat, but WoW protects secure group-frame membership and layout changes. Any pin, roster, slot, or placement change that needs a secure refresh is applied after combat ends. Change the Priority Frames keybinding out of combat."] = "Существующие рамки приоритета по-прежнему можно использовать в бою, но WoW защищает безопасное членство в группах и изменения макета. Любое изменение значка, состава, слота или размещения, требующее безопасного обновления, применяется после окончания боя. Измените привязку клавиш «Приоритетные фреймы» вне боя."
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "Соответствует глобальной раскраске Unitframe. Образец отображает текущий цвет глобальной полосы."
L["For Priority Frames, layout is profile-wide, while pins are character-specific. Visible slots can be set from one to five. Automatic tanks fill first, followed by manual pins in saved order; duplicate selections appear once. A saved player who is absent waits until that player rejoins the current group."] = "Для приоритетных фреймов макет является общим для всего профиля, а контакты зависят от символа. Видимых слотов можно установить от одного до пяти. Сначала заполняются автоматические резервуары, а затем ручные штифты в сохраненном порядке; повторяющиеся выборки появляются один раз. Отсутствующий сохраненный игрок ждет, пока этот игрок не присоединится к текущей группе."
L["How do I pin or unpin a player in Priority Frames?"] = "Как закрепить или открепить игрока в приоритетных фреймах?"
L["How do I position Priority Frames?"] = "Как расположить приоритетные рамки?"
L["How should an Augmentation Evoker use Priority Frames?"] = "Как вызывателю аугментации следует использовать приоритетные рамки?"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "Унаследовано: эта область соответствует стилю общей ауры. Включайте пользовательский стиль ауры только в том случае, если для этой области требуются другие настройки текста, пролистывания, границы или таймера."
L["Leave text"] = "Оставить текст"
L["Live "] = "Живи"
L["Live preview is unavailable for this container. Sample mode remains available."] = "Предварительный просмотр в реальном времени недоступен для этого контейнера. Режим выборки остается доступным."
L["Live preview updates after combat. Sample mode remains available."] = "Обновления предварительного просмотра в реальном времени после боя. Режим выборки остается доступным."
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "Вручную закрепите товарищей по команде, которых вы хотите оставить видимыми для мониторинга или клик-кастинга. Приоритетные рамки не решают, кто должен получить «Предвидение» или «Эбеновую мощь». Настройте «Групповые рамки» > «Ауры» > «Индикаторы заклинаний», если вы хотите, чтобы в унаследованных рамках приоритета отображались «Предвидение», «Черная мощь», «Зыбучие пески», «Взрывистая чешуя» или другие настроенные эффекты."
L["Native · "] = "Родной ·"
L["No continuous polling ticker or OnUpdate loop is used for Priority selection. It resolves the roster when configuration, pins, group state, or relevant unit identity changes require a refresh. Automatic selection reads WoW's assigned TANK role and does not inspect every group member's specialization in the background."] = "Для выбора приоритета не используется непрерывный тикер опроса или цикл OnUpdate. Он разрешает список, когда конфигурация, контакты, состояние группы или соответствующие изменения идентификации подразделения требуют обновления. Автоматический выбор считывает назначенную роль ТАНК в WoW и не проверяет специализацию каждого члена группы в фоновом режиме."
L["No live "] = "Нет живого"
L["No live member"] = "Нет живого участника"
L["No matching aura active"] = "Нет активной активной ауры"
L["No. Automatic selection currently uses only WoW's assigned TANK role. Healers, DPS, classes, specializations, and support targets must be pinned manually with the hover hotkey. This avoids background inspection or polling and keeps the selection deterministic."] = "Нет. В настоящее время при автоматическом выборе используется только назначенная WoW роль ТАНК. Целителей, DPS, классы, специализации и цели поддержки необходимо закрепить вручную с помощью горячей клавиши при наведении. Это позволяет избежать фоновой проверки или опроса и сохраняет детерминированный выбор."
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "Откройте «Групповые рамки» > «Приоритет» > «Размещение». Прикрепите полоску справа, слева, сверху или снизу активного контейнера «Вечеринка/Рейд» или выберите «Свободное положение» и используйте специальный переключатель «Приоритетные рамки» в режиме редактирования. На той же странице можно контролировать рост, интервал, зазор присоединения и смещение выравнивания."
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "Переопределение активно: этот прицел сохраняет свой собственный стиль ауры. Изменения общего стиля не заменят его, пока переопределение не будет сброшено."
L["Priority Frames does not automatically detect other players' specializations. Automatic selection currently supports WoW-assigned tanks only. Pin an Augmentation Evoker manually with the hover hotkey; Priority Frames does not choose ideal Prescience or Ebon Might targets."] = "Priority Frames не определяет автоматически специализации других игроков. Автоматический выбор в настоящее время поддерживает только танки, назначенные WoW. Закрепите Augmentation Evoker вручную с помощью горячей клавиши при наведении; Приоритетные рамки не выбирают идеальные цели «Предвидения» или «Эбеновой мощи»."
L["Priority Frames duplicate automatic tanks and manually pinned current group members into a stable extra strip without removing them from the normal Party or Raid frames. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. They work in parties, raids, and Mythic raids, inherit the active group-frame click-cast behavior, and require the matching base group frames to be enabled."] = "Рамки приоритета дублируют автоматические танки и вручную закрепляют текущих членов группы в стабильную дополнительную полосу, не удаляя их из обычных рамок группы или рейда. В группе они наследуют партийные рамки; в рейде они наследуют активные фреймы рейда или мифического рейда. Они работают в группах, рейдах и эпохальных рейдах, наследуют поведение щелчка по активному групповому фрейму и требуют включения соответствующих фреймов базовой группы."
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "Общий стиль ауры является основой для текста ауры в единичном фрейме, смахивания, границы и настроек таймера. Party и Raid — это прицелы в стиле групповых рамок со своими собственными настройками."
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "Текстуры являются общими, за исключением переопределений групповых фреймов Party/Raid. Градиенты можно настроить для отдельных единиц или групп."
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "Область действия этой группы может использовать пользовательские текстуры и градиенты. Рейд также применим к мифическому рейду."
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "Эта область может использовать пользовательские градиенты и настройки панели. Текстуры по-прежнему следуют за общими."
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "Эта область соответствует настройкам общей панели. Включите здесь пользовательские настройки, если для этой области требуются другие настройки градиентов или полос."
L["Updates after combat"] = "Обновления после боя"
L["Where can I request a Priority Frames feature?"] = "Где я могу запросить функцию Priority Frames?"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "Находясь в группе, установите горячую клавишу при наведении на «Группировать фреймы» > «Приоритет». Наведите указатель мыши на фрейм вечеринки, рейда или приоритета MSUF и нажмите горячую клавишу «Приоритетные фреймы», чтобы закрепить или открепить этого игрока. Игроков нельзя добавить, введя имя или находясь вне текущей группы; сохраненный значок отсутствия ждет и снова появляется, когда этот игрок снова присоединяется."
L["Why are my Priority Frames empty or missing?"] = "Почему мои рамки приоритета пусты или отсутствуют?"
L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "Да. Включить танки автоматически выбирает текущих членов группы, которым WoW назначена роль ТАНК, обычно включая вас и вашего второго танка. Чтобы отображался только ваш второй танк, отключите автоматические танки и вручную закрепите другой танк. Если WoW не назначил этому игроку роль ТАНКА, запасным вариантом будет закрепление вручную."
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "Да. Рамки приоритета наследуют внешний вид активного фрейма группы, рейда или мифического рейда, включая настроенные полосы, текст, ауры, индикаторы статуса и индикаторы заклинаний. Они используют одну и ту же регистрацию и поведение единиц преобразования кликов MSUF, поэтому существующие привязки преобразования щелчков также работают с дублированными фреймами."
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "Да. Рамки приоритета работают в группах, рейдах и эпохальных рейдах. В группе или подземелье они наследуют партийные рамки; в рейде они наследуют активную настройку рейда или мифического рейда. Они не создают одиночную полосу, и соответствующие базовые рамки Party или Raid должны быть включены."
