L["Brush armed: click a preview element to paint it. Right-click the swatch to disarm."] = "Кисть активна: нажмите элемент предпросмотра, чтобы окрасить его. Правый щелчок по образцу отключает кисть."
L["Class Colors"] = "Цвета классов"
