L["Name color for NPCs and bosses on all frames that follow the shared text settings."] = "Цвет имен НИП и боссов на всех рамках с общими настройками текста."
L["Name color for player characters on ALL frames - target, focus, party and raid included. NPC names use the setting next to this one."] = "Цвет имен игроков на ВСЕХ рамках, включая цель, фокус, группу и рейд. Имена НИП используют соседнюю настройку."
