--- Aura border style catalog rename (6.0 Beta 29)
L["Soft Glow"] = "Мягкое свечение"
L["Blizzard Tooltip"] = "Подсказка Blizzard"
L["Blizzard Achievement"] = "Достижение Blizzard"
L["Solid draws a crisp pixel ring around the icon. Soft Glow adds a halo, and Shadow shades the icon's own edges. The Blizzard entries and any LibSharedMedia border are drawn as edge art. Thickness scales the edge."] = "Сплошная рисует чёткую пиксельную рамку вокруг значка. Мягкое свечение добавляет ореол, а Тень затеняет собственные края значка. Записи Blizzard и любая рамка LibSharedMedia отрисовываются как краевая графика. Толщина масштабирует край."
--- Slash command registry (6.0 Beta 29)
L["Frames and Edit Mode"] = "Рамки и режим редактирования"
L["Profiles and resets"] = "Профили и сброс"
L["Other commands"] = "Другие команды"
L["Type /msuf help all to also list the diagnostic commands."] = "Введите /msuf help all, чтобы увидеть и диагностические команды."
L["List every MSUF command that is currently loaded."] = "Показывает все загруженные команды MSUF."
L["Print the addon version, the active profile and the Edit Mode state."] = "Выводит версию аддона, активный профиль и состояние режима редактирования."
L["Reload the interface, same as /rl."] = "Перезагружает интерфейс, как /rl."
L["Reload the interface."] = "Перезагружает интерфейс."
L["Toggle the absorb bars on and off."] = "Включает или выключает полосы поглощения."
L["List your profiles, or save the current settings as a new profile."] = "Показывает ваши профили или сохраняет текущие настройки в новый профиль."
L["Load one of your saved profiles."] = "Загружает один из сохранённых профилей."
L["Delete one of your saved profiles. Repeat the command to confirm."] = "Удаляет один из сохранённых профилей. Повторите команду для подтверждения."
L["Reset all frame positions and visibility to the defaults."] = "Возвращает все позиции рамок и видимость к значениям по умолчанию."
L["Reset every setting in the active profile back to the defaults."] = "Возвращает все настройки активного профиля к значениям по умолчанию."
L["Delete every MSUF profile and setting on this account."] = "Удаляет все профили и настройки MSUF в этой учётной записи."
L["Turn the Wago Analytics beta telemetry on or off."] = "Включает или выключает бета-телеметрию Wago Analytics."
L["Debug the group-frame hover and tooltip paths."] = "Отладка путей наведения и подсказок групповых рамок."
L["Print the keyboard-capture frames for movement-lock diagnosis."] = "Выводит рамки, перехватывающие клавиатуру, для диагностики блокировки движения."
L["Toggle MSUF Edit Mode. Add a unit such as player or target to open it there."] = "Переключает режим редактирования MSUF. Укажите юнит, например player или target, чтобы открыть его там."
L["Leave MSUF Edit Mode."] = "Выходит из режима редактирования MSUF."
L["Search the options menu and open the matching settings."] = "Ищет в меню настроек и открывает найденные параметры."
L["Start or resume the guided setup."] = "Запускает или продолжает пошаговую настройку."
L["Report how much of the current language is translated."] = "Сообщает, какая часть текущего языка переведена."
L["Fake an available update to test the version-check popup."] = "Имитирует доступное обновление для проверки окна версии."
L["Replay the first-start flow or the upgrade highlights."] = "Повторяет первый запуск или обзор нововведений обновления."
L["Profile which events drive the group frames in combat."] = "Профилирует, какие события управляют групповыми рамками в бою."
L["Dump the aura frame levels for a layering bug report."] = "Выводит уровни рамок аур для отчёта о наложении слоёв."
L["Check the options menu for structural problems."] = "Проверяет меню настроек на структурные проблемы."
L["Toggle the position drift debugger."] = "Переключает отладчик смещения позиций."
L["  Profile: %s (%d saved)"] = "  Профиль: %s (сохранено: %d)"
L["  Edit Mode: %s - In combat: %s"] = "  Режим редактирования: %s - В бою: %s"
