L["  /msuf load <name> switches profile, /msuf profile <name> saves a new one."] = "  /msuf load <name> меняет профиль, /msuf profile <name> сохраняет новый."
L["|cffff0000MSUF:|r Cannot change profiles while in combat."] = "|cffff0000MSUF:|r Нельзя менять профиль в бою."
L["|cffffcc00MSUF:|r Usage: /msuf load <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r Использование: /msuf load <name>. Введите /msuf profile для списка."
L["|cffff0000MSUF:|r '%s' matches more than one profile. Type the full name."] = "|cffff0000MSUF:|r '%s' совпадает с несколькими профилями. Введите полное имя."
L["|cffff0000MSUF:|r Unknown profile '%s'. Type /msuf profile to list them."] = "|cffff0000MSUF:|r Неизвестный профиль '%s'. Введите /msuf profile для списка."
L["|cffffd700MSUF:|r Profile '%s' is already active."] = "|cffffd700MSUF:|r Профиль '%s' уже активен."
L["|cffffcc00MSUF:|r Usage: /msuf delete <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r Использование: /msuf delete <name>. Введите /msuf profile для списка."
L["|cffffcc00MSUF:|r Repeat |cffffff00/msuf delete %s|r to delete that profile for good."] = "|cffffcc00MSUF:|r Повторите |cffffff00/msuf delete %s|r, чтобы окончательно удалить этот профиль."
L["|cffff0000MSUF:|r Cannot reset a profile while in combat."] = "|cffff0000MSUF:|r Нельзя сбросить профиль в бою."
L["|cffffcc00MSUF:|r This resets every setting in profile '%s', not just positions."] = "|cffffcc00MSUF:|r Это сбросит все настройки профиля '%s', а не только позиции."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default confirm|r to go ahead."] = "|cffffcc00MSUF:|r Введите |cffffff00/msuf default confirm|r, чтобы продолжить."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default|r first, then confirm it."] = "|cffffcc00MSUF:|r Сначала введите |cffffff00/msuf default|r, затем подтвердите."
L["|cffff0000MSUF:|r Unknown frame '%s'. Try player, target, focus, pet, boss or priority."] = "|cffff0000MSUF:|r Неизвестная рамка '%s'. Попробуйте player, target, focus, pet, boss или priority."
