L["Create a backup first or import into a new profile for the safest workflow."] = "Сначала создайте резервную копию или импортируйте в новый профиль - так безопаснее всего."
L["Applies the import string to the active profile. Export or copy your profile first if you want an easy backup."] = "Применяет строку импорта к активному профилю. Сначала экспортируйте или скопируйте профиль, если хотите простую резервную копию."
L["Creates a separate profile before importing so you can test the import without changing your current profile."] = "Создаёт отдельный профиль перед импортом, чтобы вы могли проверить импорт, не изменяя текущий профиль."
