L["Outline and fill behavior."] = "Поведение контура и заливки."
L["Opacity values used by range and offline states."] = "Значения непрозрачности для состояний дистанции и отключения."
L["Width can use manual bounds or follow another frame."] = "Ширина может задаваться вручную или следовать другой рамке."
L["Power textures live on the Bars page."] = "Текстуры ресурса находятся на странице «Полосы»."
L["When anchored here, Player power settings are managed by Class Resources."] = "При закреплении здесь настройки ресурса игрока управляются «Ресурсами класса»."
L["Font face follows Shared; text and color mode mirror Player HP."] = "Шрифт следует общему; текст и режим цвета повторяют здоровье игрока."
L["Local HP text uses shared face settings and a fixed white color."] = "Локальный текст здоровья использует общие настройки шрифта и фиксированный белый цвет."
L["Synchronized with Text Colors in the Fonts menu for this scope."] = "Синхронизировано с «Цветами текста» в меню шрифтов для этой области."
L["Open the shared font and colors used by every Aura scope."] = "Открывает общий шрифт и цвета, используемые всеми областями аур."
L["Tints unit-frame health bars when a configured debuff condition is active."] = "Окрашивает полосы здоровья рамок при выполнении заданного условия дебаффа."
