L["Shows the raid subgroup number from the raid roster."] = "Показывает номер подгруппы из состава рейда."
L["Shows the raid subgroup number. Party frames only display it while you are in an actual raid group."] = "Показывает номер подгруппы. Рамки группы отображают его только в настоящем рейде."
L["Independent of mouseover. Marks your current target in the selected group-frame types."] = "Не зависит от наведения мыши. Отмечает текущую цель в выбранных типах групповых рамок."
