L["Add spell"] = "Добавить заклинание"
L["Adds Blizzard's temporary weapon-enchantment buttons to the Player Buff container. This is one shared setting and uses the native aura flow without an MSUF ticker or OnUpdate."] = "Добавляет кнопки временных чар оружия от Blizzard в контейнер баффов игрока. Это одна общая настройка, использующая стандартный поток аур без таймера и OnUpdate со стороны MSUF."
L["Adds an exact harmful aura ID that is missing from the curated list. The aura is still restricted to your current target and your own aura source."] = "Добавляет точный ID вредоносной ауры, которого нет в подобранном списке. Аура по-прежнему ограничена вашей текущей целью и вашим собственным источником аур."
L["Adds one exact buff to this frame's blacklist."] = "Добавляет один точный бафф в черный список этого фрейма."
L["Adds one exact buff to this group's blacklist."] = "Добавляет один точный бафф в черный список этой группы."
L["Adds one exact harmful aura to this Target, Focus, or Boss blacklist. Blizzard applies arbitrary SpellID filters only while the unit is not assistable."] = "Добавляет одну точную вредоносную ауру в черный список цели, фокуса или босса. Blizzard применяет произвольные фильтры SpellID только пока цели нельзя помочь."
L["All Buffs"] = "Все баффы"
L["All Debuffs"] = "Все дебаффы"
L["All roles"] = "Все роли"
L["Always excludes auras without a duration, even when Blizzard token filters are disabled."] = "Всегда исключает ауры без длительности, даже если фильтры токенов Blizzard отключены."
L["Always excludes auras without a duration."] = "Всегда исключает ауры без длительности."
L["Always excludes auras without a duration. It remains active when token filters are disabled."] = "Всегда исключает ауры без длительности. Остается активным при отключенных фильтрах токенов."
L["Always excludes auras without a duration. This native rule wins over SpellID blacklists and whitelists."] = "Всегда исключает ауры без длительности. Это стандартное правило важнее черных и белых списков SpellID."
