L["Any Dispel Type"] = "Любой тип рассеивания"
L["Any dispel type"] = "Любой тип рассеивания"
L["Applicable by Me (Raid)"] = "Может наложить мной (рейд)"
L["Applies to every UnitFrame and GroupFrame icon of this Aura type. Spell Icons use the Buff appearance."] = "Применяется ко всем значкам UnitFrame и GroupFrame этого типа ауры. Значки заклинаний используют внешний вид баффов."
L["Aura sort order"] = "Порядок сортировки аур"
L["Aura sorting"] = "Сортировка аур"
L["Aura tooltip"] = "Подсказка ауры"
L["Auto breakpoints"] = "Автоматические точки перехода"
L["Auto fit"] = "Автоподгонка"
L["Auto fit pips"] = "Автоподгонка сегментов"
L["Auto-blacklist from Debuffs"] = "Автоисключение из дебаффов"
L["Auto-blacklist from player buffs"] = "Автоисключение из баффов игрока"
L["Auto: Essential Cooldowns"] = "Авто: важные способности"
L["Auto: Unit Frame"] = "Авто: фрейм юнита"
L["Auto: Utility Cooldowns"] = "Авто: вспомогательные способности"
L["Bar Only hides the aura icon. Icon + Bar keeps the icon and draws the duration bar on it."] = "Только полоса скрывает значок ауры. Значок + полоса сохраняет значок и рисует полосу длительности поверх него."
L["Bar keeps the normal statusbar. Follow Player Power mirrors the independent detached Player power shape. Orb uses a single vertical fill."] = "Полоса сохраняет обычный индикатор. Следовать ресурсу игрока повторяет форму отделенного ресурса игрока. Сфера использует одну вертикальную заливку."
L["Big Defensive"] = "Мощная защита"
L["Big Defensive Player"] = "Мощная защита (игрок)"
L["Blizzard castbar"] = "Полоса заклинаний Blizzard"
L["Blizzard ring + symbol"] = "Кольцо + символ Blizzard"
L["Blizzard symbol"] = "Символ Blizzard"
L["Blocks every aura in the selected curated MSUF set."] = "Блокирует все ауры выбранного подобранного набора MSUF."
L["Blocks only the selected aura from the curated set."] = "Блокирует только выбранную ауру из подобранного набора."
L["Cancelable Player"] = "Отменяемый (игрок)"
L["Castbar Border"] = "Рамка полосы заклинаний"
L["Changes only the detached Player Powerbar. Class Resource shape on the left changes only Class Resources."] = "Изменяет только отделенную полосу ресурса игрока. Форма ресурса класса слева меняет только ресурсы класса."
L["Class Resource Preview"] = "Предпросмотр ресурса класса"
L["Class Resource and Player Power follow existing frames. Custom uses the slider below. Width is resolved only during layout refresh."] = "Ресурс класса и ресурс игрока следуют существующим фреймам. Пользовательский использует ползунок ниже. Ширина определяется только при обновлении макета."
L["Controls only the second HP bar outline. Bar uses four outside border edges; shapes use their fixed edge texture. 0 disables only the outline."] = "Управляет только контуром второй полосы здоровья. Полоса использует четыре внешних края рамки; формы используют свою фиксированную текстуру края. 0 отключает только контур."
L["Controls only this second HP bar. The normal Player unitframe HP text remains separate."] = "Управляет только этой второй полосой здоровья. Обычный текст здоровья фрейма игрока остается отдельным."
L["Controls this aura lane independently. Always / Out of Combat / Modifier / Never under Global Style > Miscellaneous affect only unit and group frames. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Управляет этим рядом аур независимо. Всегда / Вне боя / Модификатор / Никогда в разделе Глобальный стиль > Разное влияют только на фреймы юнитов и групп. Ауры лишь повторно используют выбранный вид Blizzard/MSUF и положение курсора."
L["Cooldown swipe direction"] = "Направление заливки перезарядки"
L["Core feature enabled by default for new profiles and once for existing profiles. It works as a normal defensive buff bar without an enabled portrait. Turn this off to disable both bar and portrait-position display."] = "Основная функция, включенная по умолчанию для новых профилей и однократно для существующих. Она работает как обычная полоса защитных баффов даже без включенного портрета. Отключите, чтобы убрать и полосу, и отображение в позиции портрета."
L["Crowd Control"] = "Контроль толпы"
L["Curated Retail 12.0+ and 12.1 DoT auras. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "Подобранные ауры DoT для Retail 12.0+ и 12.1. Отслеживание ограничено юнитом этого UnitFrame и вашим собственным источником аур; настройки боссов привязываются отдельно к boss1 – boss5."
L["Custom Spell ID"] = "Пользовательский ID заклинания"
L["Dark Border"] = "Темная рамка"
L["Disabled by default. Blizzard's native implementation enables a per-frame OnUpdate for each visible aura button as soon as that aura has a calculated pandemic window; this can begin before the warning becomes visible."] = "Отключено по умолчанию. Стандартная реализация Blizzard включает покадровый OnUpdate для каждой видимой кнопки ауры, как только у этой ауры появляется рассчитанное окно пандемии; это может начаться еще до появления предупреждения."
L["Dispellable by Group"] = "Рассеивается группой"
