L["Healers only"] = "Только целители"
L["Hide permanent auras"] = "Скрывать постоянные ауры"
L["Hides this scope's selected DoT Spell IDs from the same UnitFrame's normal Debuff container while Dots on target is enabled. Blizzard's blacklist is SpellID-based, so the same spell cast by another player is hidden there too."] = "Скрывает выбранные в этой области ID заклинаний DoT из обычного контейнера дебаффов того же UnitFrame, пока включен режим DoT на цели. Черный список Blizzard работает по SpellID, поэтому то же заклинание от другого игрока там тоже скрывается."
L["Highest priority only"] = "Только наивысший приоритет"
L["Icon Border & Shadow"] = "Рамка и тень значка"
L["Include Nameplate-only"] = "Включать только индикаторы имени"
L["Inside Left"] = "Внутри слева"
L["Inside Right"] = "Внутри справа"
L["Keeps detached Player power attached to the Class Resource bar. Player power controls are disabled while this connection is active."] = "Удерживает отделенный ресурс игрока прикрепленным к полосе ресурса класса. Пока эта связь активна, настройки ресурса игрока отключены."
L["Keeps the configured portrait size and position as an invisible anchor so the defensive icon can remain there while the portrait itself is disabled."] = "Сохраняет заданные размер и положение портрета как невидимую привязку, чтобы защитный значок мог оставаться там, пока сам портрет отключен."
L["Keeps the configured portrait size, position, and shape as an invisible anchor for tracked DoTs while the portrait itself is disabled."] = "Сохраняет заданные размер, положение и форму портрета как невидимую привязку для отслеживаемых DoT, пока сам портрет отключен."
L["Limits simultaneous DoT icons at the portrait from 1 to 8. Additional icons grow outward using this DoT lane's configured Growth direction."] = "Ограничивает число одновременных значков DoT у портрета от 1 до 8. Дополнительные значки растут наружу в соответствии с настроенным направлением роста этого ряда DoT."
L["Limits the number of simultaneous defensive icons at the portrait from 1 to 8. Existing profiles remain at 1 until this value is changed."] = "Ограничивает число одновременных защитных значков у портрета от 1 до 8. Существующие профили остаются на 1, пока это значение не изменено."
L["Lists every MSUF slash command in chat, diagnostics included."] = "Выводит в чат все слэш-команды MSUF, включая диагностические."
L["Max portrait icons"] = "Макс. значков у портрета"
L["Maximum debuff duration"] = "Максимальная длительность дебаффа"
L["Moves all detached Player power text slots together. Slot X/Y controls below add per-slot offsets."] = "Перемещает все текстовые ячейки отделенного ресурса игрока вместе. Настройки X/Y ячеек ниже добавляют индивидуальные смещения."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width."] = "Выносит полосу ресурса игрока за пределы фрейма юнита. Прикрепить связывает ее со стопкой ресурсов класса; Синхронизировать только повторяет ее ширину."
L["Native Aura Flow"] = "Стандартный поток аур"
L["Blizzard Buff & Debuff Frames"] = "Панели положительных и отрицательных эффектов Blizzard"
L["Hide Blizzard Buff and Debuff Frames"] = "Скрыть панели положительных и отрицательных эффектов Blizzard"
L["Hides only Blizzard's player Buff Frame and normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Скрывает только панель положительных эффектов игрока Blizzard и обычные значки отрицательных эффектов возле мини-карты. Приватные ауры и предупреждения о смертельных эффектах остаются видимыми."
L["Buffs hidden"] = "Положительные эффекты скрыты"
L["Buffs visible"] = "Положительные эффекты видимы"
L["Debuffs hidden"] = "Отрицательные эффекты скрыты"
L["Debuffs visible"] = "Отрицательные эффекты видимы"
L["Hide Blizzard Buff Frame"] = "Скрыть панель положительных эффектов Blizzard"
L["Hide Blizzard Debuff Frame"] = "Скрыть панель отрицательных эффектов Blizzard"
L["Hides Blizzard's player Buff Frame near the minimap."] = "Скрывает панель положительных эффектов игрока Blizzard возле мини-карты."
L["Hides only Blizzard's normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Скрывает только обычные значки отрицательных эффектов Blizzard возле мини-карты. Приватные ауры и предупреждения о смертельных эффектах остаются видимыми."
L["Native size"] = "Стандартный размер"
L["Native stealable marker"] = "Стандартный маркер похищаемости"
L["Native weapon enchant auras"] = "Стандартные ауры чар оружия"
L["No roles"] = "Без ролей"
L["No width limit"] = "Без ограничения ширины"
L["Not Cancelable"] = "Неотменяемый"
L["Not Cancelable Player"] = "Неотменяемый (игрок)"
L["Off shows debuffs of any duration. Otherwise, debuffs whose total duration exceeds this number of seconds are hidden."] = "Выключено показывает дебаффы любой длительности. Иначе скрываются дебаффы, полная длительность которых превышает указанное число секунд."
L["One per dispel type"] = "По одному на тип рассеивания"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This frame's container Style stays here."] = "Открывает глобальную тему значков аур: рамка, тень, цвета, отступ рядов и стандартные чары оружия игрока. Стиль контейнера этого фрейма остается здесь."
L["Optional interpolation for this second HP bar. Off keeps direct native SetValue updates."] = "Необязательная интерполяция для этой второй полосы здоровья. Выключено сохраняет прямые стандартные обновления SetValue."
L["Optional presentation mode; the Defensive Buffs feature itself does not require a portrait. With an enabled portrait, the first icon occupies it. When the portrait is off, enable the position option below to keep the icons there; otherwise MSUF safely falls back to the normal defensive bar."] = "Необязательный режим отображения; сама функция Защитные баффы не требует портрета. При включенном портрете первый значок занимает его. Если портрет выключен, включите параметр положения ниже, чтобы значки остались там; иначе MSUF безопасно вернется к обычной защитной полосе."
L["Orb Size"] = "Размер сферы"
L["Pandemic Warning & Style"] = "Предупреждение о пандемии и стиль"
L["Pandemic color"] = "Цвет пандемии"
L["Places Player power text on the detached power bar. When off, the same Player power text remains positioned by the normal text layout."] = "Размещает текст ресурса игрока на отделенной полосе ресурса. Если выключено, тот же текст остается размещенным по обычному макету текста."
L["Places the duration bar at the top or bottom edge of the aura slot."] = "Размещает полосу длительности у верхнего или нижнего края ячейки ауры."
L["Player Text Outline"] = "Контур текста игрока"
L["Power Bar Outline"] = "Контур полосы ресурса"
L["Power Text On Bar"] = "Текст ресурса на полосе"
L["Power anchors use the Player power bar when it is visible; otherwise the HP bar falls back to the Class Resource anchor."] = "Привязки ресурса используют полосу ресурса игрока, пока она видна; иначе полоса здоровья возвращается к привязке ресурса класса."
L["Raid In Combat"] = "Рейд в бою"
L["Raid In Combat Player"] = "Рейд в бою (игрок)"
L["Raid Player"] = "Рейд (игрок)"
L["Remaining / Total"] = "Осталось / всего"
L["Remaining shrinks as the aura expires. Elapsed grows until the aura expires."] = "Осталось уменьшается по мере истечения ауры. Прошло растет до момента истечения ауры."
L["Remaining time below this value uses one decimal place. Timers show unitless seconds below 1 minute and localized minutes above it. Set 0 for whole seconds only."] = "Ниже этого значения оставшееся время отображается с одним знаком после запятой. Таймеры показывают секунды без единиц измерения до 1 минуты и локализованные минуты свыше. Значение 0 оставляет только целые секунды."
L["Remove from blacklist"] = "Убрать из черного списка"
L["Remove from whitelist"] = "Убрать из белого списка"
L["Renders a second native Player health bar. The normal Player unitframe HP bar is untouched, so you can show HP twice."] = "Рисует вторую стандартную полосу здоровья игрока. Обычная полоса здоровья фрейма игрока не затрагивается, поэтому здоровье можно показать дважды."
L["Replaces the normal DoT lane with portrait-sized icons. The first icon exactly follows this frame's portrait width, height, and shape."] = "Заменяет обычный ряд DoT значками размера портрета. Первый значок точно повторяет ширину, высоту и форму портрета этого фрейма."
L["Runs /msuf reset for frame positions and visibility."] = "Выполняет /msuf reset для положения и видимости фреймов."
L["Second Player HP Bar"] = "Вторая полоса здоровья игрока"
L["Sets the Player font scope used by detached Power text. Player Name and HP text share this outline setting."] = "Задает область шрифта игрока, используемую текстом отделенного ресурса. Имя игрока и текст здоровья используют общую настройку контура."
L["Show DoTs at portrait position"] = "Показывать DoT в позиции портрета"
L["Show buffs at portrait position"] = "Показывать баффы в позиции портрета"
L["Show cooldown text on portrait"] = "Показывать текст перезарядки на портрете"
L["Shows the active defensive buff's remaining duration over its portrait icon. Blizzard updates the text natively."] = "Показывает оставшуюся длительность активного защитного баффа поверх его значка на портрете. Blizzard обновляет текст стандартными средствами."
L["Shows the selected class/spec resource below without changing your character, spec or saved settings."] = "Показывает ниже ресурс выбранного класса или специализации, не изменяя ваш персонаж, специализацию и сохраненные настройки."
L["Shows the tracked DoT's remaining duration over its portrait icon. Blizzard updates the duration natively."] = "Показывает оставшуюся длительность отслеживаемого DoT поверх его значка на портрете. Blizzard обновляет длительность стандартными средствами."
L["Simple presets for Player power text while detached power is managed by Class Resources. Custom Slots means the existing slot layout is kept until you choose a preset."] = "Простые предустановки для текста ресурса игрока, пока отделенным ресурсом управляют ресурсы класса. Пользовательские ячейки означают, что текущая раскладка ячеек сохраняется, пока вы не выберете предустановку."
L["Smooth Fill"] = "Плавное заполнение"
L["Spell Text"] = "Текст заклинания"
L["Stops blocking this aura."] = "Снимает блокировку этой ауры."
L["Sync Width"] = "Синхронизировать ширину"
L["Tanks only"] = "Только танки"
L["Target DoT"] = "DoT на цели"
L["Target off"] = "Цель выключена"
L["Target on"] = "Цель включена"
L["Time Text"] = "Текст времени"
L["Track this predefined defensive buff. The setting applies to both the defensive bar and the optional portrait icon."] = "Отслеживать этот заранее заданный защитный бафф. Настройка действует и для защитной полосы, и для необязательного значка на портрете."
L["Tracked buffs viewer"] = "Панель отслеживаемых баффов"
L["Tracks your selected harmful auras on this UnitFrame's unit. Boss frames use their own boss1 through boss5 unit token."] = "Отслеживает выбранные вами вредоносные ауры на юните этого UnitFrame. Фреймы боссов используют собственные токены юнитов boss1 – boss5."
L["Turns Blizzard token filters on or off for this frame. The first change automatically creates frame-specific rules; migrated Shared rules remain Shared until edited."] = "Включает или отключает фильтры токенов Blizzard для этого фрейма. Первое изменение автоматически создает правила, специфичные для фрейма; перенесенные общие правила остаются общими до редактирования."
L["Unavailable cast fill"] = "Заливка недоступного заклинания"
L["Up (Single Column)"] = "Вверх (один столбец)"
L["Use Player HP Text"] = "Использовать текст здоровья игрока"
L["Use portrait position while portrait is off"] = "Использовать положение портрета при выключенном портрете"
L["Used only when this HP bar is explicitly set to Orb. Follow Player Power inherits the Player power orb size instead."] = "Используется только когда для этой полосы здоровья явно выбрана Сфера. Следовать ресурсу игрока вместо этого наследует размер сферы ресурса игрока."
L["Uses Blizzard's 12.1 AuraButton stealable filter. It adds no MSUF aura scan, ticker, or OnUpdate."] = "Использует фильтр похищаемости AuraButton из Blizzard 12.1. Он не добавляет ни сканирования аур, ни таймера, ни OnUpdate со стороны MSUF."
L["Uses Player HP text settings and copies already-rendered Player HP text when it is current. Local Text X/Y still belong to this bar."] = "Использует настройки текста здоровья игрока и копирует уже отрисованный текст, когда он актуален. Локальные значения текста X/Y по-прежнему принадлежат этой полосе."
L["Uses the Class Resource width for detached Player power without making Class Resources own the Player power controls."] = "Использует ширину ресурса класса для отделенного ресурса игрока, не передавая ресурсам класса управление его настройками."
L["Utility cooldown viewer"] = "Панель вспомогательных способностей"
L["Visible behind the filled HP amount. At 100% HP the fill covers the background; Outline 0 does not disable this texture."] = "Видно позади заполненной части здоровья. При 100% здоровья заливка закрывает фон; контур 0 не отключает эту текстуру."
L["Weapon Enchants Off"] = "Чары оружия выключены"
L["Weapon Enchants On"] = "Чары оружия включены"
L["While the defensive bar or portrait icon is enabled, hides every enabled tracked defensive from the normal player Buffs lane. Disabled defensive entries remain visible there."] = "Пока включена защитная полоса или значок на портрете, каждая включенная отслеживаемая защита скрывается из обычного ряда баффов игрока. Отключенные защитные записи остаются там видимыми."
L["Whole frame"] = "Весь фрейм"
L["Width Mode"] = "Режим ширины"

-- Menu localization pass 2026-08-06 (part 3): FAQ answers and search keyword blobs that are concatenated in source.
L["Bar Background Tint Custom color in Dark Mode background backgrond backround bg backdrop opacity alpha"] = "Оттенок фона полосы Свой цвет в темном режиме фон подложка bg непрозрачность альфа background backdrop"
L["Frame Basics Enable Load Conditions Transparency Range Fade player target focus pet gone missing invisible"] = "Основы рамки Включить Условия загрузки Прозрачность Затухание по дальности игрок цель фокус питомец отсутствует невидим"
L["Frame Basics Smooth fill Power Bar Smooth fill health animation power animation soft fill weiche Fuellung"] = "Основы рамки Плавная заливка Полоса ресурса Плавная заливка анимация здоровья анимация ресурса smooth fill"
L["General Use MSUF group frames If this switch is off enable disable turn off hide raid party mythic"] = "Общие Использовать групповые фреймы MSUF Если этот переключатель выключен включить отключить скрыть рейд группа мифический"
L["Group Frames Layout Smooth health fill Health Text Power Bar Smooth fill party raid weiche Fuellung"] = "Фреймы группы/рейда Макет Плавная заливка здоровья Текст здоровья Полоса ресурса Плавная заливка группа рейд smooth fill"
L["Group Frames Layout Transparency opacity fade target in combat out of combat alpha whole frame bars HP backdrop HP fill HP track preserve HP color"] = "Фреймы группы/рейда Макет Прозрачность непрозрачность затухание цель в бою вне боя альфа весь фрейм полосы здоровье фон заливка здоровья дорожка здоровья сохранить цвет здоровья"
L["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from each unit page > Auras or Group Frames > Auras."] = "Режим редактирования MSUF перемещает фреймы и поддерживаемые полосы произнесения. Расположение значков аур настраивается на странице каждого юнита > Ауры или в разделе Фреймы группы/рейда > Ауры."
L["Miscellaneous misc global style language menu behavior startup notices tooltips blizzard frames minimap sounds"] = "Разное общий стиль язык поведение меню уведомления при запуске подсказки фреймы Blizzard миникарта звуки"
L["Name Shortening Use custom settings for this scope Overrides Party Raid group frame name truncation font override shared changes"] = "Сокращение имени Использовать свои настройки для этой области Переопределяет группа рейд сокращение имен в групповых фреймах переопределение шрифта общие изменения"
L["Open Appearance > Auras for scope-aware cooldown text, stack text, swipe, and duration-bar styling. Timer colors remain under Colors > Auras."] = "Откройте Внешний вид > Ауры для привязанных к области текста перезарядки, текста зарядов, заливки и стиля полосы длительности. Цвета таймеров остаются в разделе Цвета > Ауры."
L["Open Boss Frames > Auras > Debuffs. SpellID blacklist entries, Blizzard filters, placement, and preview live together there; styling remains under Appearance > Auras."] = "Откройте Рамки боссов > Ауры > Дебаффы. Записи черного списка по SpellID, фильтры Blizzard, размещение и предпросмотр находятся там вместе; стиль остается в разделе Внешний вид > Ауры."
L["Open Global Style > Miscellaneous > Unitframe tooltips to control tooltip source, anchor, visibility mode, and modifier key for MSUF unit and group frames."] = "Откройте Общий стиль > Разное > Подсказки фреймов юнитов, чтобы задать источник, привязку, режим видимости и клавишу-модификатор подсказок для фреймов юнитов и групп MSUF."
L["Open Global Style > Miscellaneous for language, menu behavior, startup notices, tooltips, Blizzard frames, minimap icon, and sounds."] = "Откройте Общий стиль > Разное для языка, поведения меню, уведомлений при запуске, подсказок, фреймов Blizzard, значка миникарты и звуков."
L["Open Group Frames > Layout > Range Fade. Affects chooses frame or HP fading, and the alpha sliders control out-of-range and offline opacity."] = "Откройте Фреймы группы/рейда > Макет > Затухание по дальности. Параметр Влияет выбирает затухание фрейма или здоровья, а ползунки альфа задают непрозрачность вне дальности и в офлайне."
L["Open Group Frames > Layout > Transparency. Opacity controls in-combat and out-of-combat alpha; Fade target chooses whole frame, bars, HP, or backdrop. Backdrop and Health layers set base color, HP fill, and HP track opacity."] = "Откройте Фреймы группы/рейда > Макет > Прозрачность. Непрозрачность задает альфа в бою и вне боя; Цель затухания выбирает весь фрейм, полосы, здоровье или фон. Слои Фон и Здоровье задают базовый цвет, непрозрачность заливки и дорожки здоровья."
L["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Layout > Resource Bar > Smooth fill."] = "Откройте Фреймы группы/рейда > Макет для параметра Плавная заливка здоровья. Для полос ресурса групповых фреймов откройте Фреймы группы/рейда > Макет > Панель ресурсов > Плавная заливка."
L["Open Group Frames > Layout, choose Party, Raid, or Mythic at the top, then turn off Use MSUF group frames. Use If this switch is off to choose whether Blizzard frames show normally or both frame systems stay hidden."] = "Откройте Фреймы группы/рейда > Макет, выберите сверху Группа, Рейд или Мифический, затем отключите Использовать групповые фреймы MSUF. С помощью параметра Если этот переключатель выключен выберите, показывать ли фреймы Blizzard обычным образом или скрыть обе системы фреймов."
L["Open Group Frames > Layout. Frame Basics and Sorting control player/self visibility and how player units are ordered in group frames."] = "Откройте Фреймы группы/рейда > Макет. Основы рамки и Сортировка задают видимость игрока и вас самих, а также порядок юнитов в групповых фреймах."
L["Open Group Frames > Layout. Frame Basics/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "Откройте Фреймы группы/рейда > Макет. Основы рамки/Макет задают ширину, высоту, промежутки, столбцы и рост; Масштабирование фрейма задает поведение масштаба."
L["Open Group Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Откройте Фреймы группы/рейда > Статус и индикаторы для значков состояния, роли/лидера/помощника, проверки готовности, свечения фокуса и других индикаторов состояния групповых фреймов."
L["Open Player > Auras, then turn off Buffs for the player frame. Scope-aware text and cooldown styling remains under Appearance > Auras."] = "Откройте Игрок > Ауры и отключите Баффы для фрейма игрока. Привязанный к области стиль текста и перезарядки остается в разделе Внешний вид > Ауры."
L["Open a unit page, then use Range Fade. It is available for Target, Target of Target, Focus, Focus Target, Pet, and Boss."] = "Откройте страницу юнита и используйте Затухание по дальности. Оно доступно для цели, цели цели, фокуса, цели фокуса, питомца и босса."
L["Open the affected UnitFrame > Auras for icon size, placement, and filters. Use Appearance > Auras for scope-aware text and cooldown styling."] = "Откройте нужный UnitFrame > Ауры для размера значка, размещения и фильтров. Используйте Внешний вид > Ауры для привязанного к области текста и стиля перезарядки."
L["Open the affected UnitFrame > Auras or Group Frames > Auras and reduce visible counts, timer text, or unnecessary native filter rules."] = "Откройте нужный UnitFrame > Ауры или Фреймы группы/рейда > Ауры и уменьшите число видимых аур, текст таймеров или лишние стандартные правила фильтрации."
L["Open the affected UnitFrame > Auras, choose Buffs or Debuffs, then adjust filters, icon size, rows, caps, and spacing. Party/Raid settings are in Group Frames > Auras."] = "Откройте нужный UnitFrame > Ауры, выберите Баффы или Дебаффы, затем настройте фильтры, размер значков, ряды, ограничения и промежутки. Настройки группы и рейда находятся в разделе Фреймы группы/рейда > Ауры."
L["Open the unit page > Auras or the aura Position Popup for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "Откройте страницу юнита > Ауры или всплывающее окно позиции аур для размещения аур на фрейме юнита. Значки баффов и дебаффов настраиваются как макет аур и не перемещаются через Режим редактирования MSUF."
L["Range Fade group frame range check raid range check party range check out of range alpha offline opacity affects frame HP"] = "Затухание по дальности групповой фрейм проверка дальности рейд группа вне дальности альфа непрозрачность офлайн влияет фрейм здоровье"
L["Range Fade unit frame range check range checker distance check out of range range alpha distance fade target targettarget focus focustarget pet boss"] = "Затухание по дальности фрейм юнита проверка дальности проверка расстояния вне дальности альфа дальности цель цель цели фокус цель фокуса питомец босс"
L["Rounded Texture Rounded frame texture Unit frames Group frames Power bars Mouseover highlights rounded frames round corners"] = "Скругленная текстура Скругленная текстура фрейма Фреймы юнитов Групповые фреймы Полосы ресурса Подсветка при наведении скругленные фреймы круглые углы"
L["Status icons Indicator Level Enabled Anchor X Offset Y Offset Size Layer level text level indicator show level player level target level"] = "Значки состояния Индикатор Уровень Включено Точка крепления Смещение X Смещение Y Размер Слой текст уровня индикатор уровня уровень игрока уровень цели"
L["Text anchor offset font size layer spacing split spacing overlaps bars portraits status icons"] = "Текст точка крепления смещение размер шрифта слой порядок отрисовки промежутки раздельные промежутки перекрытия полосы портреты значки состояния"
L["Use Group Frames > Layout for frame size and spacing, Auras for Buff/Debuff placement, and Status & Indicators for fixed-position status icons."] = "Используйте Фреймы группы/рейда > Макет для размера и промежутков фреймов, Ауры для размещения баффов и дебаффов и Статус и индикаторы для значков состояния с фиксированной позицией."
L["Use Group Frames pages: Layout for size, growth, sorting, bars, and text; Auras for Buff/Debuff placement, and Status & Indicators for status icons."] = "Используйте страницы раздела Фреймы группы/рейда: Макет для размера, роста, сортировки, полос и текста; Ауры для размещения баффов и дебаффов и Статус и индикаторы для значков состояния."
L["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, text, and interrupt options."] = "Используйте страницу юнита для переключателей полосы произнесения отдельного юнита и Общий стиль > Полоса произнесения для общих текстур, направления, текста и параметров прерывания."
L["Welcome to Class Resources!\n\nWould you like to automatically set up a\ndetached Class Bar positioned above your\nEssential Cooldowns?\n\nThis configures class resource visibility,\nanchoring, width matching and detached\nPlayer Power in one click.\n\nYou can always run this later via the\n|cff00ff00Quick Setup: Class Bar|r button below."] = "Добро пожаловать в Ресурсы класса!\n\nНастроить автоматически отделенную\nклассовую полосу над вашими важными\nспособностями?\n\nЭто одним щелчком задаст видимость ресурса\nкласса, привязку, согласование ширины и\nотделенный ресурс игрока.\n\nВы всегда сможете сделать это позже кнопкой\n|cff00ff00Быстрая настройка: классовая полоса|r ниже."
L["External Edit Mode"] = "External Edit Mode"
L["Show Grid2 in MSUF Edit Mode"] = "Show Grid2 in MSUF Edit Mode"
L["Grid2 Edit Mode integration"] = "Grid2 Edit Mode integration"
L["On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."] = "On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."
L["Show Details! in MSUF Edit Mode"] = "Show Details! in MSUF Edit Mode"
L["Details! Edit Mode integration"] = "Details! Edit Mode integration"
L["On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."] = "On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."
L["Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."] = "Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."

